// 18-hole layout of the mountain course "단풍 바다 CC".
//
// World frame (metres): x = east, z = north, y = up. Headings are compass
// degrees (0 = north, 90 = east). The mountain peak is north of the
// clubhouse; the sea lies to the south and east, so most holes look out to sea.
//
// Each hole is described by par, length, the heading change from the
// previous hole, an optional dogleg and the walk from the previous green to
// this tee. Positions are generated by walking the routing, which keeps the
// data small and the layout easy to tweak; tests check that fairways never
// overlap and that every hole stays on land.

export const PEAK = Object.freeze({ x: 0, z: 350 });
export const CLUBHOUSE = Object.freeze({ x: -40, z: -380 });

// heading: absolute compass heading of the tee shot (deg).
// dogleg: { at: fraction of length, turn: deg (+ right, - left) }
// walk: [distance (m), compass heading (deg)] from previous green to this tee.
export const HOLE_SPECS = Object.freeze([
  // Front nine: west along the coast, up the western ridge, back down the spine.
  { name: '단풍 길', par: 4, length: 340, heading: 260, walk: [50, 220] },
  { name: '파도 소리', par: 3, length: 160, heading: 290, walk: [35, 270] },
  { name: '해안 숲길', par: 5, length: 470, heading: 320, dogleg: { at: 0.5, turn: 30 }, walk: [35, 300] },
  { name: '서쪽 능선', par: 4, length: 350, heading: 15, walk: [35, 0] },
  { name: '은행나무 언덕', par: 4, length: 360, heading: 30, dogleg: { at: 0.6, turn: -25 }, walk: [35, 20] },
  { name: '계곡 건너', par: 3, length: 170, heading: 95, walk: [35, 80] },
  { name: '전망대', par: 4, length: 345, heading: 120, dogleg: { at: 0.6, turn: 20 }, walk: [35, 110] },
  { name: '붉은 숲', par: 5, length: 470, heading: 200, dogleg: { at: 0.55, turn: -20 }, walk: [35, 210] },
  { name: '돌아오는 길', par: 4, length: 380, heading: 170, dogleg: { at: 0.6, turn: 15 }, walk: [35, 120] },
  // Back nine: east along the coast, up the eastern side, down the spine home.
  { name: '해송 아래', par: 4, length: 350, heading: 105, walk: [120, 100] },
  { name: '등대 홀', par: 3, length: 165, heading: 60, walk: [35, 100] },
  { name: '해안 절벽', par: 5, length: 490, heading: 45, dogleg: { at: 0.55, turn: -25 }, walk: [35, 60] },
  { name: '산허리', par: 4, length: 340, heading: 345, dogleg: { at: 0.6, turn: -20 }, walk: [35, 0] },
  { name: '노을 그린', par: 3, length: 150, heading: 300, walk: [35, 320] },
  { name: '낙엽 계단', par: 4, length: 360, heading: 250, dogleg: { at: 0.6, turn: -15 }, walk: [35, 260] },
  { name: '단풍 터널', par: 5, length: 465, heading: 190, walk: [35, 200] },
  { name: '바람의 언덕', par: 4, length: 300, heading: 80, walk: [35, 80] },
  { name: '귀로', par: 4, length: 390, heading: 243, walk: [35, 200] },
]);

const rad = (d) => (d * Math.PI) / 180;
export const dirOf = (headingDeg) => ({ x: Math.sin(rad(headingDeg)), z: Math.cos(rad(headingDeg)) });

function step(p, dist, headingDeg) {
  const d = dirOf(headingDeg);
  return { x: p.x + d.x * dist, z: p.z + d.z * dist };
}

/**
 * Build hole geometry: tee, optional dogleg point, green, centreline.
 * A spec either walks from the previous green (walk/heading/length/dogleg)
 * or gives explicit points (tee, optional corner, green).
 */
export function buildHoles(specs = HOLE_SPECS, start = CLUBHOUSE) {
  const holes = [];
  let cursor = { ...start };
  specs.forEach((s, i) => {
    const tee = s.tee ? { ...s.tee } : step(cursor, s.walk[0], s.walk[1]);
    const pts = [tee];
    let green;
    if (s.green) {
      if (s.corner) pts.push({ ...s.corner });
      green = { ...s.green };
    } else if (s.dogleg) {
      const corner = step(tee, s.length * s.dogleg.at, s.heading);
      pts.push(corner);
      green = step(corner, s.length * (1 - s.dogleg.at), s.heading + s.dogleg.turn);
    } else {
      green = step(tee, s.length, s.heading);
    }
    pts.push(green);
    const greenRadius = s.par === 3 ? 14 : 16;
    holes.push({
      number: i + 1,
      name: s.name,
      par: s.par,
      length: s.length ?? Math.round(pts.reduce((a, p, k) => (k ? a + Math.hypot(p.x - pts[k - 1].x, p.z - pts[k - 1].z) : 0), 0)),
      // Optional forced carry (e.g. over the sea): [from, to] as fractions of the hole.
      carry: s.carry ?? null,
      tee,
      green,
      path: pts,
      fairwayHalfWidth: s.par === 3 ? 0 : s.par === 5 ? 20 : 18,
      greenRadius,
      // Pin offset inside the green (deterministic per hole).
      pin: {
        x: green.x + Math.sin(i * 2.1) * greenRadius * 0.35,
        z: green.z + Math.cos(i * 1.7) * greenRadius * 0.35,
      },
    });
    cursor = green;
  });
  return holes;
}

/** Distance from point to segment and the parameter along it. */
export function segDistance(px, pz, a, b) {
  const vx = b.x - a.x;
  const vz = b.z - a.z;
  const len2 = vx * vx + vz * vz || 1;
  let t = ((px - a.x) * vx + (pz - a.z) * vz) / len2;
  t = Math.max(0, Math.min(1, t));
  const cx = a.x + vx * t;
  const cz = a.z + vz * t;
  return { d: Math.hypot(px - cx, pz - cz), t };
}

/** Closest point on a hole's centreline: distance and fraction along the hole. */
export function pathDistance(px, pz, path) {
  let best = { d: Infinity, s: 0 };
  let acc = 0;
  let total = 0;
  for (let i = 0; i + 1 < path.length; i++) total += Math.hypot(path[i + 1].x - path[i].x, path[i + 1].z - path[i].z);
  for (let i = 0; i + 1 < path.length; i++) {
    const seg = Math.hypot(path[i + 1].x - path[i].x, path[i + 1].z - path[i].z);
    const r = segDistance(px, pz, path[i], path[i + 1]);
    if (r.d < best.d) best = { d: r.d, s: (acc + r.t * seg) / total };
    acc += seg;
  }
  return best;
}
